// Some portions generated by Claude
// Execute the actual browser Worker asset with a Node message-port adapter.
// This verifies the shipped dependency bundle, not DOM/browser interaction.
import {parentPort, workerData} from 'node:worker_threads';
globalThis.self = globalThis;
globalThis.location = new URL(workerData.asset);
globalThis.postMessage = message => parentPort.postMessage(message);
await import(workerData.asset);
parentPort.on('message', data => globalThis.onmessage({data}));
